import styles from './SummaryCard.module.css';
import { useState, useEffect } from 'react';

const SummaryCard = () => {
  // Estado inicial con valores por defecto
  const [financialData, setFinancialData] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    balance: 0,
    currentBalance: 0,
  });

  // Cargar datos al inicio y escuchar cambios
  useEffect(() => {
    const loadData = () => {
      const savedData = localStorage.getItem('financialData');
      if (savedData) {
        const parsedData = JSON.parse(savedData);
        // Asegurarse de que todos los campos existan
        setFinancialData({
          totalIncome: parsedData.totalIncome || 0,
          totalExpenses: parsedData.totalExpenses || 0, // Corregido: "totalExpenses" (antes tenía typo)
          balance: parsedData.balance || 0,
          currentBalance: parsedData.currentBalance || 0,
        });
      }
    };

    loadData();
    window.addEventListener('storage', loadData);

    return () => window.removeEventListener('storage', loadData);
  }, []);

  // Función para limpiar datos (ahora más robusta)
  const handleClearData = () => {
    const resetData = {
      totalIncome: 0,
      totalExpenses: 0,
      balance: 0,
      currentBalance: 0,
    };
    setFinancialData(resetData);
    localStorage.setItem('financialData', JSON.stringify(resetData));
  };

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses.toFixed(2)}</p> {/* Corregido: "totalExpenses" */}
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance.toFixed(2)}</p>
      </div>
      <button 
        onClick={handleClearData}
        className={styles.clearButton}
      >
        Limpiar Datos
      </button>
    </div>
  );
};

export default SummaryCard;
